@@ -38,9 +38,9 @@
 function openInventory(){modal('🎒 Barang bawaan','<p class="modal-desc">Sentuh barang untuk menggunakannya. Ruang terbatas, manfaatkan peti penyimpanan.</p><div class="inventory-list">'+Object.keys(names).filter(k=>(s.inv[k]||0)>0).map(k=>`<div class="inv-item" data-use="${k}"><span>${icons[k]} ${names[k]}</span><b>×${s.inv[k]}</b></div>`).join('')+'</div><p class="notice">Kapasitas '+count()+' / '+s.capacity+'. Tekan barang untuk menggunakannya (makanan/minuman).</p>');$('#modalBody').querySelectorAll('[data-use]').forEach(e=>e.onclick=()=>useItem(e.dataset.use))}
 function useItem(k){if(!(s.inv[k]>0))return;if(k==='ikan'||k==='ikanBesar'||k==='ikanLangka'){s.inv[k]--;s.food=Math.min(100,s.food+(k==='ikan'?19:k==='ikanBesar'?33:45));toast('Kamu memakan '+names[k]+'.')}else if(k==='buah'){s.inv[k]--;s.food=Math.min(100,s.food+13);s.water=Math.min(100,s.water+7);toast('Buah segar memulihkan lapar dan haus.')}else if(k==='air'){s.inv[k]--;s.water=Math.min(100,s.water+32);toast('Air tawar menyegarkan tubuh.')}else if(k==='bed'){s.time=(s.time+8)%24;s.food=Math.max(0,s.food-5);s.water=Math.max(0,s.water-6);s.stamina=100;s.health=Math.min(100,s.health+8);toast('Kamu beristirahat dengan nyenyak.')}else{toast('Barang ini belum bisa digunakan langsung.')}update();openInventory();save()}
 function gather(){if(s.dead)return;if(s.stamina<8){toast('Stamina terlalu rendah. Istirahat sejenak.');return}s.stamina-=8;s.explores++;s.distance+=Math.round(20+Math.random()*50);s.playerX+=Math.round(Math.random()*3-1);s.playerY+=Math.round(Math.random()*3-1);let roll=Math.random(),item,n=1;if(roll<.28){item='kayu';n=1+Math.floor(Math.random()*2);s.woodGathered+=n}else if(roll<.46)item='plastik';else if(roll<.59)item='tali';else if(roll<.70)item='daun';else if(roll<.77)item='besi';else if(roll<.84)item='buah';else if(roll<.91)item='batu';else if(roll<.96)item='botol';else item='kerang';if(add(item,n)){xp(2);toast(`Kamu menemukan ${n>1?n+' ':''}${names[item]}!`)}if(s.explores>=4&&!s.visitedIsland){s.visitedIsland=true;add('buah');add('daun');xp(20);toast('Daratan terlihat! Pulau tropis ditemukan! 🏝️')}else if(s.explores===12&&!s.shipwreck){s.shipwreck=true;add('besi');add('botol');toast('Kapal karam ditemukan di kejauhan! ⚓')}if(Math.random()<.14){const event=['Pesan dalam botol terdampar. Ada tulisan: “Jangan ikuti cahaya biru.”','Seekor lumba-lumba melompat di sisi rakit.','Kamu melihat kapal misterius di cakrawala…','Peti terapung tersangkut di antara ombak!'];let msg=event[Math.floor(Math.random()*event.length)];if(msg.includes('Peti')){add('kayu',2);add('besi');msg+=' +2 kayu, +1 besi'}toast(msg)}update();save()}
 function fish(){if(s.stamina<12){toast('Stamina kurang untuk memancing.');return}if(!s.inv.kail){toast('Kamu perlu membuat kail terlebih dahulu.');openCraft();return}s.stamina-=8;s.fishGame=true;modal('🎣 Memancing','<p class="fish-instruction">Tahan tombol <b>Tarik!</b> saat ikan berada di zona hijau. Lepas untuk menunggu umpan.</p><div class="fish-box"><div class="fish-target" id="fishTarget"></div><div class="fish-marker" id="fishMarker">🐟</div></div><div class="fish-instruction" id="fishStatus">Bidik ikan, lalu tarik!</div><button id="reel" style="width:100%;margin-top:12px;background:#a9e3b2;color:#12301f;border:0;border-radius:8px;padding:11px;font-weight:700">TARIK!</button>');let x=2,dir=1,tx=42,hit=0,tick=setInterval(()=>{if(!s.fishGame){clearInterval(tick);return}x+=dir*2.7;if(x>90||x<2)dir*=-1;tx=(tx+1.5)%100;let m=$('#fishMarker'),t=$('#fishTarget');if(m)m.style.left=x+'%';if(t)t.style.left=tx+'%';},80);let reel=$('#reel');reel.onpointerdown=e=>{e.preventDefault();if(x>tx-8&&x<tx+14){hit++;$('#fishStatus').textContent=`Tepat sasaran! ${hit}/3`;if(hit>=3){clearInterval(tick);s.fishGame=false;closeModal();let rare=Math.random()<.12?'ikanLangka':Math.random()<.2?'ikanBesar':'ikan';if(add(rare)){s.fishCaught++;s.food=Math.min(100,s.food+3);xp(12);toast(`Kamu menangkap ${names[rare]}!`)}update();save()} }else{$('#fishStatus').textContent='Meleset! Tunggu ikan masuk zona.';hit=Math.max(0,hit-1)}};reel.onpointerup=()=>{} }
-$('#gather').onclick=gather;document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>({craft:openCraft,build:openBuild,map:openMap}[b.dataset.panel])());$('#close').onclick=closeModal;$('#overlay').onclick=e=>{if(e.target.id==='overlay')closeModal()};$('#sound').onclick=()=>{s.sound=!s.sound;$('#sound').textContent=s.sound?'♫':'♪̸';toast(s.sound?'Suara diaktifkan':'Suara dimatikan')};$('#quickbar').onclick=e=>{const el=e.target.closest('.slot');if(el){s.selected=[...el.parentElement.children].indexOf(el)}};$('#quickbar').addEventListener('dblclick',e=>{const el=e.target.closest('.slot');if(el)useItem(['kayu','ikan','air','buah'][[...el.parentElement.children].indexOf(el)])});$('#restart').onclick=()=>{localStorage.removeItem('lostAtSeaSave');location.reload()};document.querySelectorAll('[data-move]').forEach(b=>b.onpointerdown=()=>{if(s.stamina>2){s.stamina-=2;s.playerX+=b.dataset.move==='left'?-1:b.dataset.move==='right'?1:0;s.playerY+=b.dataset.move==='up'?-1:b.dataset.move==='down'?1:0;s.distance+=3;update()}});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key.toLowerCase()==='e')gather();if(e.key.toLowerCase()==='f')fish();if(e.key.toLowerCase()==='i')openInventory();if(e.key==='ArrowUp'||e.key==='w')s.playerY--;if(e.key==='ArrowDown'||e.key==='s')s.playerY++;if(e.key==='ArrowLeft'||e.key==='a')s.playerX--;if(e.key==='ArrowRight'||e.key==='d')s.playerX++});
+$('#gather').onclick=gather;document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>({craft:openCraft,build:openBuild,map:openMap,inventory:openInventory}[b.dataset.panel])());$('#fishButton').onclick=fish;$('#close').onclick=closeModal;$('#overlay').onclick=e=>{if(e.target.id==='overlay')closeModal()};$('#sound').onclick=()=>{s.sound=!s.sound;$('#sound').textContent=s.sound?'♫':'♪̸';toast(s.sound?'Suara diaktifkan':'Suara dimatikan')};$('#quickbar').onclick=e=>{const el=e.target.closest('.slot');if(el){s.selected=[...el.parentElement.children].indexOf(el)}};$('#quickbar').addEventListener('dblclick',e=>{const el=e.target.closest('.slot');if(el)useItem(['kayu','ikan','air','buah'][[...el.parentElement.children].indexOf(el)])});$('#restart').onclick=()=>{localStorage.removeItem('lostAtSeaSave');location.reload()};document.querySelectorAll('[data-move]').forEach(b=>b.onpointerdown=()=>{if(s.stamina>2){s.stamina-=2;s.playerX+=b.dataset.move==='left'?-1:b.dataset.move==='right'?1:0;s.playerY+=b.dataset.move==='up'?-1:b.dataset.move==='down'?1:0;s.distance+=3;update()}});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key.toLowerCase()==='e')gather();if(e.key.toLowerCase()==='f')fish();if(e.key.toLowerCase()==='i')openInventory();if(e.key==='ArrowUp'||e.key==='w')s.playerY--;if(e.key==='ArrowDown'||e.key==='s')s.playerY++;if(e.key==='ArrowLeft'||e.key==='a')s.playerX--;if(e.key==='ArrowRight'||e.key==='d')s.playerX++});
 function tick(){if(s.dead)return;s.time+=.035;if(s.time>=24){s.time=0;s.day++;toast(`Hari ${s.day}. Lautan masih luas…`)}s.food=Math.max(0,s.food-.045);s.water=Math.max(0,s.water-.065);s.stamina=Math.min(100,s.stamina+.035);if(s.food<=0||s.water<=0)s.health=Math.max(0,s.health-.13);if(s.weather==='Hujan'||s.weather==='Badai')s.temp=Math.max(33,s.temp-.003);else s.temp=Math.min(37,s.temp+.002);if(s.time>19||s.time<5)s.temp=Math.max(33,s.temp-.006);s.weatherTimer--;if(s.weatherTimer<=0){s.weather=['Cerah','Cerah','Berawan','Berawan','Hujan','Kabut','Badai'][Math.floor(Math.random()*7)];s.weatherTimer=70+Math.random()*100;if(s.weather==='Badai'){if(!s.buildings.includes('jangkar')&&Math.random()<.4){s.raft=Math.max(2,s.raft-1);toast('Badai merusak satu lantai rakit!');}else toast('Badai besar! Bertahanlah di rakit!')}else toast(`Cuaca berubah: ${s.weather}`)}if(s.temp<34||s.temp>39)s.health-=.03;update();save()}
 let time=0;function draw(t){const w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.floor(w*dpr)||canvas.height!==Math.floor(h*dpr)){canvas.width=w*dpr;canvas.height=h*dpr}ctx.setTransform(dpr,0,0,dpr,0,0);let night=s.time>19||s.time<5;let g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,night?'#092f50':'#08718a');g.addColorStop(.5,night?'#104967':'#14829a');g.addColorStop(1,night?'#092a49':'#0a5d79');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);time=t*.0002;
 // pixel waves
 for(let i=0;i<26;i++){let y=((i*43+time*160)% (h+60))-30;for(let j=0;j<7;j++){let x=(j*117+Math.sin(time*2+i)*22+i*19)%(w+80)-20;ctx.globalAlpha=.08+((i+j)%3)*.035;ctx.fillStyle=(i+j)%2?'#9ae7cf':'#acd9df';ctx.fillRect(x,y,30+(j%3)*9,2)}}ctx.globalAlpha=1;

