 function openMap(){modal('⌖ Peta penjelajahan','<p class="modal-desc">Peta sederhana wilayah yang telah kamu jelajahi.</p><div class="mapbox"><div class="map-player">🛶</div>'+(s.visitedIsland?'<div class="map-island">🏝️</div>':'')+(s.shipwreck?'<div style="position:absolute;left:25%;top:65%;font-size:22px">⚓</div>':'')+'</div><p class="notice">Posisi: '+Math.floor(s.playerX)+', '+Math.floor(s.playerY)+' · Jarak tempuh '+Math.floor(s.distance)+' m.<br>🌊 Samudra terbuka '+(s.visitedIsland?' · 🏝️ Pulau ditemukan':' · Belum ada pulau ditemukan')+'</p><div class="cards"><div class="card"><h3>🧭 Jelajahi laut</h3><p>Gunakan energi untuk mencari daratan dan benda terapung.</p><button id="mapExplore">Jelajahi sekarang</button></div><div class="card"><h3>📖 Panduan pemula</h3><p>Mulai dengan mencari kayu, buat kail, lalu buat pemurni air. Makan dan minum sebelum indikator habis.</p><button id="guideClose">Paham</button></div></div>');$('#mapExplore').onclick=()=>{closeModal();gather()};$('#guideClose').onclick=closeModal}
 function openInventory(){modal('🎒 Barang bawaan','<p class="modal-desc">Sentuh barang untuk menggunakannya. Ruang terbatas, manfaatkan peti penyimpanan.</p><div class="inventory-list">'+Object.keys(names).filter(k=>(s.inv[k]||0)>0).map(k=>`<div class="inv-item" data-use="${k}"><span>${icons[k]} ${names[k]}</span><b>×${s.inv[k]}</b></div>`).join('')+'</div><p class="notice">Kapasitas '+count()+' / '+s.capacity+'. Tekan barang untuk menggunakannya (makanan/minuman).</p>');$('#modalBody').querySelectorAll('[data-use]').forEach(e=>e.onclick=()=>useItem(e.dataset.use))}
 function useItem(k){if(!(s.inv[k]>0))return;if(k==='ikanMatang'){s.inv[k]--;s.food=Math.min(100,s.food+30);toast('Ikan panggang mengenyangkan.')}else if(k==='ikan'||k==='ikanBesar'||k==='ikanLangka'){s.inv[k]--;s.food=Math.min(100,s.food+(k==='ikan'?19:k==='ikanBesar'?33:45));toast('Kamu memakan '+names[k]+'.')}else if(k==='buah'){s.inv[k]--;s.food=Math.min(100,s.food+13);s.water=Math.min(100,s.water+7);toast('Buah segar memulihkan lapar dan haus.')}else if(k==='air'){s.inv[k]--;s.water=Math.min(100,s.water+32);toast('Air tawar menyegarkan tubuh.')}else if(k==='bed'){s.time=(s.time+8)%24;s.food=Math.max(0,s.food-5);s.water=Math.max(0,s.water-6);s.stamina=100;s.health=Math.min(100,s.health+8);toast('Kamu beristirahat dengan nyenyak.')}else{toast('Barang ini belum bisa digunakan langsung.')}update();openInventory();save()}
 function gather(){if(s.dead)return;if(s.stamina<8){toast('Stamina terlalu rendah. Istirahat sejenak.');return}s.stamina-=8;s.explores++;s.distance+=Math.round(20+Math.random()*50);s.playerX+=Math.round(Math.random()*3-1);s.playerY+=Math.round(Math.random()*3-1);let roll=Math.random(),item,n=1;if(roll<.28){item='kayu';n=1+Math.floor(Math.random()*2);s.woodGathered+=n}else if(roll<.46)item='plastik';else if(roll<.59)item='tali';else if(roll<.70)item='daun';else if(roll<.77)item='besi';else if(roll<.84)item='buah';else if(roll<.91)item='batu';else if(roll<.96)item='botol';else item='kerang';if(add(item,n)){xp(2);toast(`Kamu menemukan ${n>1?n+' ':''}${names[item]}!`)}if(s.explores>=4&&!s.visitedIsland){s.visitedIsland=true;add('buah');add('daun');xp(20);toast('Daratan terlihat! Pulau tropis ditemukan! 🏝️')}else if(s.explores===12&&!s.shipwreck){s.shipwreck=true;add('besi');add('botol');toast('Kapal karam ditemukan di kejauhan! ⚓')}if(Math.random()<.14){const event=['Pesan dalam botol terdampar. Ada tulisan: “Jangan ikuti cahaya biru.”','Seekor lumba-lumba melompat di sisi rakit.','Kamu melihat kapal misterius di cakrawala…','Peti terapung tersangkut di antara ombak!'];let msg=event[Math.floor(Math.random()*event.length)];if(msg.includes('Peti')){add('kayu',2);add('besi');msg+=' +2 kayu, +1 besi'}toast(msg)}update();save()}
